"""Fixed candidate scoring on targets generated by a held-out random chain."""
import argparse
import importlib.util
import json
import os
from pathlib import Path
import shutil
import traceback

import numpy as np

from experiments import pc_jepa_multiroot_action_effect_dev_20261105_codex as old

ROOT, sha = old.ROOT, old.sha
OUT = ROOT / "results/pc_jepa_reachable_random_goal_dev_20261105_codex"
PROTOCOL = ROOT.parent / "docs/PC_JEPA_REACHABLE_RANDOM_GOAL_DEV_PROTOCOL_20261105_CODEX.md"
SEEDS = (2026110601, 2026110602, 2026110603, 2026110604)


def bank():
    actions = np.repeat(np.random.default_rng(2026110610).uniform(-1, 1, (65, 3, 2))
                        .astype(np.float32), 5, axis=1)
    if len({a.tobytes() for a in actions}) != 65:
        raise ValueError("duplicate actions")
    return actions


def physical():
    if OUT.exists():
        raise FileExistsError(OUT)
    overlay = (ROOT / ".jepa-physics-site").resolve()
    if os.environ.get("PYTHONPATH") != str(overlay):
        raise ValueError("exact physics overlay required")
    import gym
    import pymunk
    import skimage
    if ((gym.__version__, pymunk.version, skimage.__version__) != ("0.23.1", "6.8.0", "0.25.2")
            or any(not Path(m.__file__).resolve().is_relative_to(overlay) for m in (gym, pymunk, skimage))):
        raise ValueError("physics dependency mismatch")
    base = old.old.prior.helpers(ROOT)
    runtime, parent = base.load_runtime(ROOT)
    if runtime.probe(ROOT, parent, ROOT / f"results/{base.RUNTIME}/manifest_frozen.json")["status"] != \
            "native_import_ready_physics_not_executed":
        raise ValueError("runtime preflight")
    spec = importlib.util.spec_from_file_location("reachable_goal_native", ROOT / runtime.ENV_REL)
    native = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(native)
    stats = old.old.prior.native_stats(ROOT)
    warm = np.asarray(old.old.prior.SCHEDULE, np.float64).reshape(15, 2)[:10]
    actions = bank()
    dependencies = [Path(__file__), PROTOCOL, Path(old.__file__), old.WORKER, old.META,
                    ROOT / runtime.ENV_REL, ROOT / "external/jepa-wms/app/plan_common/datasets/pusht_dset.py"]
    bindings = {str(p): sha(p) for p in dependencies}
    OUT.mkdir()
    summary = {"status": "running", "bindings": bindings, "roots": [], "root_seeds": SEEDS}
    try:
        with (OUT / "evaluation_reference.npy").open("xb") as f:
            np.save(f, actions[64])
        for index, seed in enumerate(SEEDS):
            base_dir = OUT / f"root_{index}"
            (base_dir / "input").mkdir(parents=True)
            (base_dir / "output").mkdir()
            histories, terminal_rgb, states = None, [], []
            for chain in actions:
                env = native.PushTEnv(**base.CTOR)
                try:
                    env.seed(seed)
                    obs, state = env.reset()
                    images, props, start_states = [obs["visual"].copy()], [obs["proprio"].copy()], [state.copy()]
                    for step, action in enumerate(warm):
                        obs, _, done, info = env.step(action.copy())
                        if done:
                            raise ValueError("early termination in warmup")
                        if step in (4, 9):
                            images.append(obs["visual"].copy())
                            props.append(obs["proprio"].copy())
                            start_states.append(info["state"].copy())
                    current = (np.stack(images), np.stack(props), np.stack(start_states))
                    if histories is None:
                        histories = current
                    else:
                        for actual, expected in zip(current, histories, strict=True):
                            np.testing.assert_array_equal(actual, expected)
                    for action in chain.astype(np.float64):
                        obs, _, done, info = env.step(action)
                        if done:
                            raise ValueError("early termination in candidate chain")
                    terminal_rgb.append(obs["visual"].copy())
                    states.append(info["state"].copy())
                finally:
                    env.close()
            rgb, props, start_states = histories
            prop = (props.astype(np.float32) - stats["PROPRIO_MEAN"]) / stats["PROPRIO_STD"]
            history_u = (100 * warm).astype(np.float32) / np.float32(100)
            packets = ((history_u - stats["ACTION_MEAN"]) / stats["ACTION_STD"]).reshape(2, 10)
            goal_rgb, target = terminal_rgb[64], states[64]
            with (base_dir / "input/context.npz").open("xb") as f:
                np.savez_compressed(f, rgb_history=rgb, goal_rgb=goal_rgb[None], normalized_proprio=prop,
                                    normalized_history_packets=packets, action_mean=stats["ACTION_MEAN"],
                                    action_std=stats["ACTION_STD"], carry=np.empty((0, 2), np.float32))
            with (base_dir / "input/bank.npy").open("xb") as f:
                np.save(f, actions[:64])
            with (base_dir / "input/images.npz").open("xb") as f:
                np.savez_compressed(f, goal_rgb=goal_rgb, terminal_rgb=np.stack(terminal_rgb[:64]))
            shutil.copyfile(old.META, base_dir / "input/model_metadata.json")
            with (base_dir / "physical.npz").open("xb") as f:
                np.savez_compressed(f, states=np.stack(states[:64]), goal_state=target,
                                    history_states=start_states)
            summary["roots"].append({"root": index, "count": 64, "status": "completed",
                                     "physical_sha256": sha(base_dir / "physical.npz"),
                                     "inputs": {p.name: sha(p) for p in sorted((base_dir / "input").iterdir())}})
            print(f"root {index}: 64 candidates + held-out reference", flush=True)
        if any(sha(Path(p)) != v for p, v in bindings.items()):
            raise ValueError("dependency changed")
        summary.update(status="completed", reference_sha256=sha(OUT / "evaluation_reference.npy"))
    except Exception:
        summary.update(status="failed", error=traceback.format_exc())
    with (OUT / "physical.json").open("x") as f:
        json.dump(summary, f, indent=2, allow_nan=False)
        f.write("\n")
    if summary["status"] != "completed":
        raise RuntimeError(summary["error"])


def verify():
    data = json.loads((OUT / "physical.json").read_text())
    if (data["status"] != "completed" or len(data["roots"]) != len(SEEDS)
            or data["reference_sha256"] != sha(OUT / "evaluation_reference.npy")
            or any(sha(Path(p)) != v for p, v in data["bindings"].items())):
        raise ValueError("physical seal mismatch")
    for row in data["roots"]:
        path = OUT / f"root_{row['root']}"
        if (sha(path / "physical.npz") != row["physical_sha256"]
                or any(sha(path / "input" / p) != v for p, v in row["inputs"].items())):
            raise ValueError("input changed")
    return data


def neural():
    verify()
    for i in range(len(SEEDS)):
        path = OUT / f"root_{i}"
        if (path / "output/receipt.json").exists():
            raise FileExistsError(path / "output/receipt.json")
        old.neural.launch(path, "experiments.pc_jepa_v22_contact_latent_error_worker_20261105_codex")
        print(f"root {i}: 64 predictions and encodings", flush=True)


def summarize():
    verify()
    rows = []
    for i in range(len(SEEDS)):
        path = OUT / f"root_{i}"
        receipt = json.loads((path / "output/receipt.json").read_text())
        if (receipt["status"] != "completed" or receipt["worker_sha256"] != sha(old.WORKER)
                or receipt["latents_sha256"] != sha(path / "output/latents.npz")
                or any(receipt[k] != sha(path / "input" / n) for k, n in (
                    ("context_sha256", "context.npz"), ("bank_sha256", "bank.npy"),
                    ("images_sha256", "images.npz"), ("metadata_sha256", "model_metadata.json")))):
            raise ValueError("neural receipt mismatch")
        with np.load(path / "output/latents.npz", allow_pickle=False) as data:
            predicted, actual, goal = [data[k].astype(np.float64) for k in ("predicted", "actual", "goal")]
        with np.load(path / "physical.npz", allow_pickle=False) as data:
            states, target, history = (data[k] for k in ("states", "goal_state", "history_states"))
        pred_score = ((predicted - goal) ** 2).mean(axis=(1, 2))
        actual_score = ((actual - goal) ** 2).mean(axis=(1, 2))
        distance = np.linalg.norm(states[:, :4] - target[:4], axis=1)
        angle = np.abs((states[:, 4] - target[4] + np.pi) % (2 * np.pi) - np.pi)
        success = (distance < 20) & (angle < np.pi / 9)
        choices = {}
        for name, score in (("predicted", pred_score), ("actual_encoded", actual_score)):
            order = np.argsort(score, kind="stable")
            hits = np.flatnonzero(success[order])
            chosen = int(order[0])
            choices[name] = {"index": chosen, "success": bool(success[chosen]),
                             "first_success_rank": int(hits[0] + 1) if len(hits) else None,
                             "score": float(score[chosen]), "joint_xy_error": float(distance[chosen]),
                             "angle_error": float(angle[chosen])}
        rows.append({"root": i, "success_count": int(success.sum()),
                     "goal_object_displacement": float(np.linalg.norm(target[2:4] - history[-1, 2:4])),
                     "goal_angle_displacement": float(abs((target[4] - history[-1, 4] + np.pi) % (2*np.pi) - np.pi)),
                     "mean_prediction_mse": float(np.mean((predicted-actual)**2)),
                     "predicted_vs_actual_score": old.independent_order(pred_score, actual_score),
                     "choices": choices, "success_by_index": success.tolist(),
                     "latents_sha256": sha(path / "output/latents.npz")})
    output = {"status": "completed", "physical_sha256": sha(OUT / "physical.json"), "rows": rows,
              "scope": "four development roots, constructed targets, 64 queried candidate chains"}
    with (OUT / "report.json").open("x") as f:
        json.dump(output, f, indent=2, allow_nan=False)
        f.write("\n")
    print(json.dumps(output, indent=2), flush=True)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("phase", choices=("physical", "neural", "summarize"))
    phase = parser.parse_args().phase
    print(f"Reachable random-goal diagnostic: {phase}", flush=True)
    {"physical": physical, "neural": neural, "summarize": summarize}[phase]()
